:root {
  color-scheme: light;
  --bg: #f4f7f3;
  --surface: #ffffff;
  --surface-muted: #edf3ed;
  --ink: #17211b;
  --muted: #65736a;
  --line: #d7e0d8;
  --accent: #256c4a;
  --accent-strong: #164c35;
  --accent-soft: #dcece2;
  --warning: #8a5a16;
  --danger: #b42318;
  --radius: 8px;
  --shadow: 0 18px 50px rgb(39 64 48 / 0.08);
  font-family:
    ui-sans-serif,
    system-ui,
    -apple-system,
    BlinkMacSystemFont,
    "Segoe UI",
    sans-serif;
  background: var(--bg);
  color: var(--ink);
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  min-width: 320px;
  min-height: 100dvh;
  background:
    linear-gradient(180deg, rgb(255 255 255 / 0.72), transparent 380px),
    var(--bg);
}

button,
textarea,
input {
  font: inherit;
}

button {
  cursor: pointer;
}

button:disabled {
  cursor: not-allowed;
  opacity: 0.56;
}

.app-shell {
  display: grid;
  grid-template-columns: 280px minmax(0, 1fr);
  min-height: 100dvh;
}

.sidebar {
  position: sticky;
  top: 0;
  height: 100dvh;
  display: flex;
  flex-direction: column;
  gap: 20px;
  padding: 22px 16px;
  border-right: 1px solid var(--line);
  background: rgb(255 255 255 / 0.78);
  backdrop-filter: blur(18px);
}

.brand {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 6px 8px 14px;
  border-bottom: 1px solid var(--line);
}

.brand-mark,
.header-icon {
  display: grid;
  place-items: center;
  width: 40px;
  height: 40px;
  flex: 0 0 auto;
  border-radius: var(--radius);
  color: var(--accent-strong);
  background: var(--accent-soft);
}

.brand strong,
.brand span {
  display: block;
}

.brand strong {
  font-size: 15px;
}

.brand span {
  margin-top: 2px;
  color: var(--muted);
  font-size: 12px;
}

.nav-list {
  display: grid;
  gap: 4px;
}

.nav-item {
  display: flex;
  align-items: center;
  gap: 10px;
  width: 100%;
  min-height: 40px;
  padding: 9px 11px;
  border: 1px solid transparent;
  border-radius: var(--radius);
  color: var(--muted);
  background: transparent;
  text-align: left;
}

.nav-item:hover,
.nav-item:focus-visible {
  color: var(--ink);
  background: var(--surface-muted);
  outline: none;
}

.nav-item.active {
  color: var(--accent-strong);
  border-color: #c7dccd;
  background: var(--accent-soft);
}

.compliance-note {
  display: flex;
  gap: 10px;
  margin-top: auto;
  padding: 12px;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  color: var(--muted);
  background: #f8faf7;
}

.compliance-note p {
  margin: 0;
  font-size: 12px;
  line-height: 1.5;
}

.main {
  width: min(100%, 1480px);
  margin: 0 auto;
  padding: 24px;
}

.topbar {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 24px;
  margin-bottom: 24px;
  padding: 20px;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  background: rgb(255 255 255 / 0.76);
  box-shadow: var(--shadow);
}

.topbar h1 {
  max-width: 780px;
  margin: 3px 0 0;
  font-size: clamp(28px, 4vw, 44px);
  line-height: 1.08;
  letter-spacing: 0;
}

.eyebrow {
  margin: 0;
  color: var(--accent);
  font-size: 13px;
  font-weight: 700;
}

.topbar-actions,
.section-action,
.mock-actions,
.sticky-actions {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: 10px;
  flex-wrap: wrap;
}

.button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  min-height: 38px;
  padding: 9px 14px;
  border: 1px solid transparent;
  border-radius: var(--radius);
  font-weight: 700;
  text-decoration: none;
  transition:
    transform 150ms ease,
    border-color 150ms ease,
    background-color 150ms ease;
}

.button:active {
  transform: translateY(1px);
}

.button.primary {
  color: #fff;
  background: var(--accent-strong);
}

.button.primary:hover,
.button.primary:focus-visible {
  background: #0f3d2b;
  outline: 3px solid rgb(37 108 74 / 0.22);
}

.button.secondary {
  color: var(--ink);
  border-color: var(--line);
  background: #fff;
}

.button.secondary:hover,
.button.secondary:focus-visible {
  border-color: #b6c8bb;
  background: #f7faf7;
  outline: none;
}

.button.text-button {
  min-height: 32px;
  padding: 4px 0;
  color: var(--accent);
  background: transparent;
}

.button.danger {
  color: #fff;
  background: var(--danger);
}

.file-button input {
  position: absolute;
  inline-size: 1px;
  block-size: 1px;
  opacity: 0;
  pointer-events: none;
}

.page-section {
  display: grid;
  gap: 20px;
}

.metrics-grid,
.plan-grid,
.business-panel,
.privacy-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 14px;
}

.metric-card,
.panel,
.question-card,
.plan-card,
.privacy-item,
.workflow-step,
.report-hero {
  border: 1px solid var(--line);
  border-radius: var(--radius);
  background: var(--surface);
  box-shadow: var(--shadow);
}

.metric-card {
  display: grid;
  gap: 8px;
  padding: 16px;
}

.metric-card > svg {
  color: var(--accent);
}

.metric-card span,
.metric-card p,
.metric-card small {
  color: var(--muted);
}

.metric-card span {
  font-size: 13px;
  font-weight: 700;
}

.metric-card strong {
  font-size: 34px;
  line-height: 1;
}

.metric-card p {
  min-height: 38px;
  margin: 0;
  font-size: 13px;
  line-height: 1.45;
}

.workflow {
  display: grid;
  grid-template-columns: repeat(5, minmax(0, 1fr));
  gap: 10px;
}

.workflow-step {
  position: relative;
  display: grid;
  grid-template-columns: auto 1fr auto;
  align-items: center;
  gap: 8px;
  min-height: 110px;
  padding: 14px;
  text-align: left;
}

.workflow-step > span {
  display: grid;
  place-items: center;
  width: 28px;
  height: 28px;
  border-radius: 50%;
  color: #fff;
  background: var(--accent);
  font-size: 13px;
  font-weight: 800;
}

.workflow-step small {
  grid-column: 2 / 3;
  color: var(--muted);
  line-height: 1.5;
}

.workflow-step:hover,
.workflow-step:focus-visible {
  border-color: #b3cbbb;
  outline: none;
  transform: translateY(-1px);
}

.split-grid,
.editor-grid,
.mock-layout,
.answer-layout {
  display: grid;
  gap: 16px;
}

.split-grid {
  grid-template-columns: repeat(2, minmax(0, 1fr));
}

.editor-grid {
  grid-template-columns: minmax(0, 1.1fr) minmax(360px, 0.9fr);
  align-items: start;
}

.mock-layout {
  grid-template-columns: 340px minmax(0, 1fr);
  align-items: start;
}

.answer-layout {
  grid-template-columns: repeat(2, minmax(0, 1fr));
}

.section-header {
  display: grid;
  grid-template-columns: auto 1fr auto;
  align-items: center;
  gap: 14px;
  padding: 16px;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  background: rgb(255 255 255 / 0.76);
}

.section-header h2,
.panel h2 {
  margin: 0;
  font-size: 20px;
}

.section-header p {
  margin: 4px 0 0;
  color: var(--muted);
  line-height: 1.5;
}

.panel {
  min-width: 0;
  padding: 16px;
}

.panel > header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  margin-bottom: 14px;
}

.gap-list,
.evidence-list,
.rewrite-list,
.action-list,
.dimension-list,
.insight-stack,
.question-rail {
  display: grid;
  gap: 10px;
}

.gap-item,
.evidence-item,
.rewrite-list article,
.rail-item,
.turn-feedback {
  padding: 12px;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  background: #fbfcfb;
}

.gap-item span,
.evidence-item span,
.question-meta span,
.large-question span,
.rail-item span {
  display: inline-flex;
  width: fit-content;
  margin-bottom: 6px;
  padding: 3px 8px;
  border-radius: 999px;
  color: var(--accent-strong);
  background: var(--accent-soft);
  font-size: 12px;
  font-weight: 800;
}

.gap-item.gap span {
  color: #7a4b00;
  background: #fbefd7;
}

.gap-item.risk span {
  color: #8b251f;
  background: #fbe3e1;
}

.gap-item strong,
.evidence-item strong {
  display: block;
}

.gap-item p,
.evidence-item p,
.rewrite-list p,
.evidence-item small,
.action-list,
.number-list,
.risk-copy,
.answer-text,
.question-card p,
.plan-card p,
.privacy-item p {
  color: var(--muted);
  line-height: 1.58;
}

.action-list,
.number-list,
.plan-card ul {
  margin: 0;
  padding: 0;
  list-style: none;
}

.action-list li,
.plan-card li {
  display: flex;
  gap: 9px;
  align-items: flex-start;
}

.action-list svg,
.plan-card svg {
  flex: 0 0 auto;
  margin-top: 2px;
  color: var(--accent);
}

.text-editor,
.mock-room textarea {
  width: 100%;
  min-height: 620px;
  padding: 16px;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  color: var(--ink);
  background: #fff;
  line-height: 1.64;
  resize: vertical;
}

.text-editor:focus,
.mock-room textarea:focus {
  border-color: var(--accent);
  outline: 3px solid rgb(37 108 74 / 0.16);
}

.sticky-actions {
  position: sticky;
  bottom: 12px;
  padding: 10px;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  background: rgb(255 255 255 / 0.88);
  backdrop-filter: blur(12px);
}

.rewrite-list article {
  display: grid;
  gap: 8px;
}

.rewrite-list .before {
  margin: 0;
  color: #7a4b00;
}

.rewrite-list .after {
  margin: 0;
  color: var(--ink);
  font-weight: 700;
}

.tag-block + .tag-block {
  margin-top: 16px;
}

.tags {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-top: 9px;
}

.tags span {
  padding: 6px 9px;
  border: 1px solid #c7dccd;
  border-radius: 999px;
  color: var(--accent-strong);
  background: #f4faf6;
  font-size: 13px;
  font-weight: 700;
}

.number-list {
  counter-reset: number;
  display: grid;
  gap: 10px;
}

.number-list li {
  counter-increment: number;
  display: grid;
  grid-template-columns: 28px 1fr;
  gap: 8px;
  color: var(--muted);
  line-height: 1.55;
}

.number-list li::before {
  content: counter(number);
  display: grid;
  place-items: center;
  width: 24px;
  height: 24px;
  border-radius: 50%;
  color: var(--accent);
  background: var(--accent-soft);
  font-size: 12px;
  font-weight: 800;
}

.segmented {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  padding: 8px;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  background: rgb(255 255 255 / 0.74);
}

.segmented button {
  min-height: 34px;
  padding: 7px 12px;
  border: 1px solid transparent;
  border-radius: var(--radius);
  color: var(--muted);
  background: transparent;
  font-weight: 700;
}

.segmented button.active,
.segmented button:hover,
.segmented button:focus-visible {
  color: var(--accent-strong);
  border-color: #c7dccd;
  background: var(--accent-soft);
  outline: none;
}

.question-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 14px;
}

.question-card {
  display: grid;
  gap: 12px;
  padding: 16px;
}

.question-card h3 {
  margin: 0;
  font-size: 17px;
  line-height: 1.45;
}

.question-card p {
  margin: 0;
}

.question-meta {
  display: flex;
  justify-content: space-between;
  gap: 8px;
}

.large-question h2 {
  margin: 0;
  font-size: 28px;
  line-height: 1.24;
}

.large-question p {
  color: var(--muted);
}

.answer-text,
.risk-copy {
  margin: 0;
}

.evidence-list.compact .evidence-item p {
  margin-bottom: 0;
}

.question-rail {
  max-height: calc(100dvh - 180px);
  overflow: auto;
}

.rail-item {
  display: grid;
  gap: 4px;
  width: 100%;
  color: var(--ink);
  text-align: left;
}

.rail-item strong {
  font-size: 14px;
  line-height: 1.46;
}

.rail-item.active {
  border-color: #9fc2aa;
  background: var(--accent-soft);
}

.mock-room {
  display: grid;
  gap: 14px;
  padding: 16px;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  background: var(--surface);
  box-shadow: var(--shadow);
}

.mock-room h2 {
  margin: 0;
  font-size: 26px;
  line-height: 1.28;
}

.mock-room textarea {
  min-height: 330px;
}

.timer-strip {
  display: inline-flex;
  width: fit-content;
  align-items: center;
  gap: 8px;
  padding: 7px 10px;
  border-radius: var(--radius);
  color: var(--accent-strong);
  background: var(--accent-soft);
  font-size: 13px;
  font-weight: 800;
}

.turn-feedback {
  display: flex;
  align-items: center;
  gap: 12px;
  border-color: #b7d0bd;
  background: #f4faf6;
}

.turn-feedback strong {
  font-size: 28px;
  color: var(--accent-strong);
}

.turn-feedback p {
  margin: 0;
  color: var(--muted);
}

.report-hero {
  display: grid;
  grid-template-columns: auto 1fr;
  align-items: center;
  gap: 18px;
  padding: 20px;
}

.report-hero div {
  min-width: 180px;
}

.report-hero span,
.report-hero small {
  color: var(--muted);
  font-weight: 700;
}

.report-hero strong {
  display: inline-block;
  margin: 0 4px;
  font-size: 64px;
  line-height: 1;
}

.report-hero p {
  margin: 0;
  color: var(--muted);
  font-size: 18px;
  line-height: 1.55;
}

.dimension-row {
  display: grid;
  grid-template-columns: 92px 1fr 40px;
  gap: 10px;
  align-items: center;
}

.dimension-row meter {
  width: 100%;
  height: 12px;
}

.dimension-row strong {
  text-align: right;
}

.plan-grid {
  grid-template-columns: repeat(4, minmax(0, 1fr));
}

.plan-card {
  position: relative;
  display: grid;
  gap: 12px;
  padding: 18px;
}

.plan-card.recommended {
  border-color: #93bd9f;
  background: #f7fbf8;
}

.plan-card h3,
.plan-card p {
  margin: 0;
}

.plan-card > strong {
  font-size: 30px;
}

.plan-card ul {
  display: grid;
  gap: 8px;
}

.recommend-badge {
  width: fit-content;
  padding: 4px 8px;
  border-radius: 999px;
  color: #fff;
  background: var(--accent);
  font-size: 12px;
  font-weight: 800;
}

.business-panel {
  grid-template-columns: repeat(3, minmax(0, 1fr));
}

.privacy-grid {
  grid-template-columns: repeat(4, minmax(0, 1fr));
}

.privacy-item {
  display: grid;
  gap: 8px;
  padding: 16px;
}

.privacy-item svg {
  color: var(--accent);
}

.privacy-item p {
  margin: 0;
}

@media (max-width: 1180px) {
  .app-shell {
    grid-template-columns: 1fr;
  }

  .sidebar {
    position: static;
    height: auto;
    border-right: 0;
    border-bottom: 1px solid var(--line);
  }

  .nav-list {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }

  .compliance-note {
    margin-top: 0;
  }

  .workflow,
  .metrics-grid,
  .plan-grid,
  .privacy-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .question-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .editor-grid,
  .mock-layout {
    grid-template-columns: 1fr;
  }

  .question-rail {
    max-height: none;
  }
}

@media (max-width: 760px) {
  .main {
    padding: 14px;
  }

  .topbar,
  .section-header,
  .report-hero {
    grid-template-columns: 1fr;
  }

  .topbar {
    flex-direction: column;
  }

  .topbar-actions,
  .section-action {
    width: 100%;
    justify-content: stretch;
  }

  .button {
    width: 100%;
  }

  .nav-list,
  .workflow,
  .metrics-grid,
  .split-grid,
  .answer-layout,
  .question-grid,
  .plan-grid,
  .business-panel,
  .privacy-grid {
    grid-template-columns: 1fr;
  }

  .text-editor {
    min-height: 420px;
  }

  .dimension-row {
    grid-template-columns: 78px 1fr 36px;
  }
}

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    scroll-behavior: auto !important;
    transition-duration: 0.01ms !important;
    animation-duration: 0.01ms !important;
  }
}

