  { id: "mock", label: "模拟面试", icon: Mic },
  { id: "report", label: "复盘报告", icon: Target },
  { id: "subscription", label: "订阅", icon: WalletCards },
  { id: "privacy", label: "隐私", icon: ShieldCheck },
