function loadInitialState(): WorkspaceState {
  try {
    const raw = window.localStorage.getItem(STORAGE_KEY);
    if (!raw) return createWorkspaceState();
    const parsed = JSON.parse(raw) as Pick<WorkspaceState, "resumeText" | "jobText" | "mockTurns">;
    return recomputeWorkspace(parsed.resumeText, parsed.jobText, parsed.mockTurns ?? []);
  } catch {
    return createWorkspaceState();
  }
}

export function App() {
  const [workspace, setWorkspace] = useState<WorkspaceState>(() => loadInitialState());
  const [stage, setStage] = useState<StageId>("dashboard");

  useEffect(() => {
    window.localStorage.setItem(
      STORAGE_KEY,
      JSON.stringify({
        resumeText: workspace.resumeText,
        jobText: workspace.jobText,
        mockTurns: workspace.mockTurns,
      }),
    );
  }, [workspace]);

  const selectedQuestion = workspace.questions.find((question) => question.id === workspace.selectedQuestionId) ?? workspace.questions[0];
  const selectedAnswer = workspace.answers.find((answer) => answer.questionId === selectedQuestion?.id);

  const updateInputs = (resumeText: string, jobText: string) => {
    setWorkspace(recomputeWorkspace(resumeText, jobText, workspace.mockTurns));
  };

  const addMockTurn = (turn: MockTurn) => {
    setWorkspace((current) => {
      const otherTurns = current.mockTurns.filter((item) => item.questionId !== turn.questionId);
      const mockTurns = [...otherTurns, turn];
      return {
        ...current,
        mockTurns,
        report: buildInterviewReport(mockTurns, current.questions, current.matchReport),
      };
    });
  };

  const resetWorkspace = () => {
    const fresh = createWorkspaceState();
    setWorkspace(fresh);
    setStage("dashboard");
  };

  return (
    <div className="app-shell">
      <aside className="sidebar" aria-label="主导航">
        <div className="brand">
          <div className="brand-mark" aria-hidden="true">
            <GraduationCap size={21} />
          </div>
          <div>
            <strong>校招准备台</strong>
            <span>AI 求职训练 MVP</span>
          </div>
        </div>
        <nav className="nav-list">
          {NAV_ITEMS.map((item) => {
            const Icon = item.icon;
            return (
              <button key={item.id} className={stage === item.id ? "nav-item active" : "nav-item"} onClick={() => setStage(item.id)}>
                <Icon size={18} />
                <span>{item.label}</span>
              </button>
            );
          })}
        </nav>
        <div className="compliance-note">
          <ShieldCheck size={18} />
          <p>当前版本仅用于面前准备和模拟复盘，不提供隐蔽真实面试辅助。</p>
        </div>
      </aside>

      <main className="main">
        <header className="topbar">
          <div>
            <p className="eyebrow">Web MVP</p>
            <h1>围绕一个目标 JD，把求职准备做成闭环</h1>
          </div>
          <div className="topbar-actions">
            <button className="button secondary" onClick={resetWorkspace}>
              <RotateCcw size={17} />
              重置示例
            </button>
            <button className="button primary" onClick={() => setStage("resume")}>
              开始诊断
              <ArrowRight size={17} />
            </button>
          </div>
        </header>

        {stage === "dashboard" && <Dashboard workspace={workspace} setStage={setStage} />}
        {stage === "resume" && <ResumeCenter workspace={workspace} updateInputs={updateInputs} />}
        {stage === "job" && <JobWorkbench workspace={workspace} updateInputs={updateInputs} />}
        {stage === "questions" && (
          <QuestionBank
            workspace={workspace}
            selectQuestion={(questionId) => {
              setWorkspace((current) => ({ ...current, selectedQuestionId: questionId }));
              setStage("answers");
            }}
          />
        )}
        {stage === "answers" && selectedQuestion && selectedAnswer && (
          <AnswerStudio
            question={selectedQuestion}
            answer={selectedAnswer}
            workspace={workspace}
            onMock={() => setStage("mock")}
          />
        )}
        {stage === "mock" && selectedQuestion && selectedAnswer && (
          <MockInterview
            workspace={workspace}
            selectedQuestion={selectedQuestion}
            selectedAnswer={selectedAnswer}
            setSelectedQuestion={(questionId) => setWorkspace((current) => ({ ...current, selectedQuestionId: questionId }))}
            onSubmitTurn={addMockTurn}
          />
        )}
        {stage === "report" && <ReportView workspace={workspace} setStage={setStage} />}
        {stage === "subscription" && <SubscriptionView />}
        {stage === "privacy" && <PrivacyView onClear={resetWorkspace} />}
      </main>
    </div>
  );
}

