function ResumeCenter({
  workspace,
  updateInputs,
}: {
  workspace: WorkspaceState;
  updateInputs: (resumeText: string, jobText: string) => void;
}) {
  const [draft, setDraft] = useState(workspace.resumeText);

  useEffect(() => {
    setDraft(workspace.resumeText);
  }, [workspace.resumeText]);

  const onFile = async (event: ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;
    const text = await file.text();
    setDraft(text);
  };

  return (
    <section className="page-section">
      <EditorHeader
        icon={Upload}
        title="简历中心"
        description="当前 MVP 支持 TXT/Markdown 文本导入；PDF/DOCX 解析接口已在路线图中预留。"
        action={
          <label className="button secondary file-button">
            <Upload size={17} />
            导入文本
            <input type="file" accept=".txt,.md,.markdown" onChange={onFile} />
          </label>
        }
      />
      <div className="editor-grid">
        <TextEditor value={draft} onChange={setDraft} ariaLabel="简历文本" />
        <div className="insight-stack">
          <Panel title="证据库">
            <div className="evidence-list">
              {workspace.resume.evidence.slice(0, 7).map((item) => (
                <article key={item.id} className="evidence-item">
                  <span>{item.type}</span>
                  <strong>{item.title}</strong>
                  <p>{item.detail}</p>
                  <small>{item.impact}</small>
                </article>
              ))}
            </div>
          </Panel>
          <Panel title="逐句优化建议">
            <div className="rewrite-list">
              {workspace.matchReport.rewriteSuggestions.map((item) => (
                <article key={item.before}>
                  <p className="before">{item.before}</p>
                  <p className="after">{item.after}</p>
                  <small>{item.reason}</small>
                </article>
              ))}
            </div>
          </Panel>
        </div>
      </div>
      <div className="sticky-actions">
        <button className="button primary" onClick={() => updateInputs(draft, workspace.jobText)}>
          <RefreshCw size={17} />
          重新诊断
        </button>
      </div>
    </section>
  );
}

