function QuestionBank({
  workspace,
  selectQuestion,
}: {
  workspace: WorkspaceState;
  selectQuestion: (questionId: string) => void;
}) {
  const categories = useMemo(() => Array.from(new Set(workspace.questions.map((item) => item.category))), [workspace.questions]);
  const [category, setCategory] = useState<string>("全部");
  const filtered = category === "全部" ? workspace.questions : workspace.questions.filter((item) => item.category === category);

  return (
    <section className="page-section">
      <EditorHeader icon={ClipboardList} title="高概率问题库" description="问题都基于目标 JD 和简历证据生成，并标注为什么会被问。" />
