function MockInterview({
  workspace,
  selectedQuestion,
  selectedAnswer,
  setSelectedQuestion,
  onSubmitTurn,
}: {
  workspace: WorkspaceState;
  selectedQuestion: InterviewQuestion;
  selectedAnswer: AnswerDraft;
  setSelectedQuestion: (questionId: string) => void;
  onSubmitTurn: (turn: MockTurn) => void;
}) {
  const existingTurn = workspace.mockTurns.find((turn) => turn.questionId === selectedQuestion.id);
  const [answer, setAnswer] = useState(existingTurn?.answer ?? "");

  useEffect(() => {
    const nextTurn = workspace.mockTurns.find((turn) => turn.questionId === selectedQuestion.id);
    setAnswer(nextTurn?.answer ?? "");
  }, [selectedQuestion.id, workspace.mockTurns]);

  const submit = (event: FormEvent) => {
    event.preventDefault();
    if (!answer.trim()) return;
    onSubmitTurn(evaluateMockTurn(selectedQuestion, answer, selectedAnswer));
  };

  return (
    <section className="page-section">
      <EditorHeader icon={Mic} title="文本模拟面试" description="MVP 先做文本计时模拟。语音练习将在 P1 作为面前准备功能加入。" />
      <div className="mock-layout">
        <aside className="question-rail">
          {workspace.questions.slice(0, 10).map((question) => {
            const done = workspace.mockTurns.some((turn) => turn.questionId === question.id);
            return (
              <button key={question.id} className={selectedQuestion.id === question.id ? "rail-item active" : "rail-item"} onClick={() => setSelectedQuestion(question.id)}>
                <span>{question.category}</span>
                <strong>{question.question}</strong>
                {done && <Check size={15} />}
              </button>
            );
          })}
        </aside>
        <form className="mock-room" onSubmit={submit}>
          <div className="timer-strip">
            <Timer size={18} />
            <span>建议作答时长 60 到 90 秒</span>
          </div>
          <h2>{selectedQuestion.question}</h2>
          <textarea value={answer} onChange={(event) => setAnswer(event.target.value)} placeholder="按 STAR 写下你的回答：背景、任务、动作、结果..." />
          <div className="mock-actions">
            <button className="button secondary" type="button" onClick={() => setAnswer(selectedAnswer.concise)}>
              使用精简版草稿
            </button>
            <button className="button primary" type="submit" disabled={!answer.trim()}>
              提交复盘
            </button>
          </div>
          {existingTurn && (
            <div className="turn-feedback" role="status">
              <strong>{existingTurn.score}/100</strong>
              <p>{existingTurn.feedback}</p>
            </div>
          )}
        </form>
      </div>
    </section>
  );
}

