function MetricCard({
  label,
  value,
  suffix,
  detail,
  icon: Icon,
}: {
  label: string;
  value: string;
  suffix: string;
  detail: string;
  icon: typeof BarChart3;
}) {
  return (
    <article className="metric-card">
      <Icon size={20} />
      <span>{label}</span>
      <div>
        <strong>{value}</strong>
        <small>{suffix}</small>
      </div>
      <p>{detail}</p>
    </article>
  );
}

function Panel({
  title,
  children,
  actionLabel,
  onAction,
}: {
  title: string;
  children: React.ReactNode;
  actionLabel?: string;
  onAction?: () => void;
}) {
  return (
    <section className="panel">
      <header>
        <h2>{title}</h2>
        {actionLabel && (
          <button className="button text-button" onClick={onAction}>
            {actionLabel}
            <ArrowRight size={16} />
          </button>
        )}
      </header>
      {children}
    </section>
  );
}

function EditorHeader({
  icon: Icon,
  title,
  description,
  action,
}: {
  icon: typeof FileText;
  title: string;
  description: string;
  action?: React.ReactNode;
}) {
  return (
    <div className="section-header">
      <div className="header-icon">
        <Icon size={20} />
      </div>
      <div>
        <h2>{title}</h2>
        <p>{description}</p>
      </div>
      {action && <div className="section-action">{action}</div>}
    </div>
  );
}

function TextEditor({ value, onChange, ariaLabel }: { value: string; onChange: (value: string) => void; ariaLabel: string }) {
  return <textarea className="text-editor" value={value} onChange={(event) => onChange(event.target.value)} aria-label={ariaLabel} spellCheck={false} />;
}

function GapList({ workspace }: { workspace: WorkspaceState }) {
  return (
    <div className="gap-list">
      {workspace.matchReport.gaps.map((gap) => (
        <article key={`${gap.label}-${gap.description}`} className={`gap-item ${gap.type}`}>
          <span>{gap.type === "match" ? "已匹配" : gap.type === "gap" ? "待补齐" : "风险"}</span>
          <strong>{gap.label}</strong>
          <p>{gap.description}</p>
        </article>
      ))}
    </div>
  );
}

function TagBlock({ title, items }: { title: string; items: string[] }) {
  return (
    <div className="tag-block">
      <strong>{title}</strong>
      <div className="tags">
        {(items.length > 0 ? items : ["待补充"]).map((item) => (
          <span key={item}>{item}</span>
        ))}
      </div>
    </div>
  );
}

