            const done = workspace.mockTurns.some((turn) => turn.questionId === question.id);
            return (
              <button key={question.id} className={selectedQuestion.id === question.id ? "rail-item active" : "rail-item"} onClick={() => setSelectedQuestion(question.id)}>
                <span>{question.category}</span>
                <strong>{question.question}</strong>
                {done && <Check size={15} />}
              </button>
            );
          })}
        </aside>
        <form className="mock-room" onSubmit={submit}>
          <div className="timer-strip">
            <Timer size={18} />
            <span>建议作答时长 60 到 90 秒</span>
          </div>
          <h2>{selectedQuestion.question}</h2>
          <textarea value={answer} onChange={(event) => setAnswer(event.target.value)} placeholder="按 STAR 写下你的回答：背景、任务、动作、结果..." />
          <div className="mock-actions">
            <button className="button secondary" type="button" onClick={() => setAnswer(selectedAnswer.concise)}>
              使用精简版草稿
            </button>
            <button className="button primary" type="submit" disabled={!answer.trim()}>
              提交复盘
            </button>
          </div>
          {existingTurn && (
            <div className="turn-feedback" role="status">
              <strong>{existingTurn.score}/100</strong>
              <p>{existingTurn.feedback}</p>
            </div>
          )}
        </form>
      </div>
    </section>
  );
}

function ReportView({ workspace, setStage }: { workspace: WorkspaceState; setStage: (stage: StageId) => void }) {
  const dimensions = [
    ["完整度", workspace.report.dimensions.completeness],
    ["岗位相关性", workspace.report.dimensions.relevance],
    ["证据强度", workspace.report.dimensions.evidenceStrength],
    ["表达结构", workspace.report.dimensions.structure],
    ["风险控制", workspace.report.dimensions.riskControl],
  ];

  return (
    <section className="page-section">
      <EditorHeader icon={Target} title="复盘报告" description="从完整度、岗位相关性、证据强度、表达结构和风险控制五个维度评估。" action={<button className="button secondary"><Download size={17} />导出报告</button>} />
      <div className="report-hero">
        <div>
          <span>综合分</span>
          <strong>{workspace.report.overallScore}</strong>
          <small>/100</small>
        </div>
        <p>{workspace.report.summary}</p>
      </div>
      <div className="split-grid">
        <Panel title="五维评分">
          <div className="dimension-list">
            {dimensions.map(([label, value]) => (
              <div key={label as string} className="dimension-row">
                <span>{label}</span>
                <meter min="0" max="100" value={value as number} />
                <strong>{value}</strong>
              </div>
            ))}
          </div>
        </Panel>
        <Panel title="下一轮训练清单" actionLabel="继续模拟" onAction={() => setStage("mock")}>
          <ul className="action-list">
            {workspace.report.nextActions.map((item) => (
              <li key={item}>
                <Check size={16} />
                <span>{item}</span>
              </li>
            ))}
          </ul>
        </Panel>
      </div>
    </section>
  );
}

function SubscriptionView() {
