              ))}
            </ul>
          </article>
        ))}
      </div>
      <div className="business-panel">
        <MetricCard label="CAC 目标" value="80" suffix="元内" detail="B2C 付费用户获客成本上限。" icon={BarChart3} />
        <MetricCard label="付费转化" value="3-5" suffix="%" detail="Beta 阶段健康线。" icon={Sparkles} />
        <MetricCard label="模型成本" value="8-15" suffix="元" detail="每月活跃付费用户成本目标。" icon={Database} />
      </div>
    </section>
