function PrivacyView({ onClear }: { onClear: () => void }) {
  return (
    <section className="page-section">
      <EditorHeader icon={Lock} title="隐私与数据管理" description="默认不把用户简历、JD、模拟回答或录音用于模型训练；实时辅助上线前需另做法律评审。" />
      <div className="privacy-grid">
        {[
          ["数据最小化", "仅保存完成诊断和复盘所需的简历、JD、回答和报告数据。"],
          ["本地 MVP", "当前原型使用 localStorage 持久化，便于演示，不上传到远端服务。"],
          ["可删除", "用户可以一键清除本地数据；正式版需提供账号级导出和删除能力。"],
          ["合规边界", "产品定位为面前准备与复盘，不鼓励在未授权真实面试中使用 AI 作答。"],
        ].map(([title, detail]) => (
          <article key={title} className="privacy-item">
            <ShieldCheck size={20} />
            <strong>{title}</strong>
            <p>{detail}</p>
          </article>
        ))}
      </div>
      <button className="button danger" onClick={onClear}>
        <Trash2 size={17} />
        清除本地演示数据
      </button>
    </section>
  );
}

function MetricCard({
  label,
  value,
  suffix,
  detail,
  icon: Icon,
}: {
  label: string;
  value: string;
  suffix: string;
  detail: string;
  icon: typeof BarChart3;
}) {
  return (
    <article className="metric-card">
      <Icon size={20} />
      <span>{label}</span>
      <div>
        <strong>{value}</strong>
        <small>{suffix}</small>
      </div>
      <p>{detail}</p>
    </article>
  );
}

function Panel({
  title,
  children,
  actionLabel,
  onAction,
}: {
  title: string;
  children: React.ReactNode;
  actionLabel?: string;
  onAction?: () => void;
}) {
  return (
    <section className="panel">
      <header>
        <h2>{title}</h2>
        {actionLabel && (
          <button className="button text-button" onClick={onAction}>
            {actionLabel}
            <ArrowRight size={16} />
          </button>
        )}
      </header>
      {children}
    </section>
  );
}

function EditorHeader({
  icon: Icon,
  title,
  description,
  action,
}: {
  icon: typeof FileText;
  title: string;
  description: string;
  action?: React.ReactNode;
}) {
  return (
    <div className="section-header">
      <div className="header-icon">
        <Icon size={20} />
      </div>
      <div>
        <h2>{title}</h2>
        <p>{description}</p>
      </div>
      {action && <div className="section-action">{action}</div>}
    </div>
  );
}

function TextEditor({ value, onChange, ariaLabel }: { value: string; onChange: (value: string) => void; ariaLabel: string }) {
  return <textarea className="text-editor" value={value} onChange={(event) => onChange(event.target.value)} aria-label={ariaLabel} spellCheck={false} />;
}

function GapList({ workspace }: { workspace: WorkspaceState }) {
  return (
    <div className="gap-list">
      {workspace.matchReport.gaps.map((gap) => (
        <article key={`${gap.label}-${gap.description}`} className={`gap-item ${gap.type}`}>
          <span>{gap.type === "match" ? "已匹配" : gap.type === "gap" ? "待补齐" : "风险"}</span>
          <strong>{gap.label}</strong>
          <p>{gap.description}</p>
        </article>
      ))}
    </div>
  );
}

function TagBlock({ title, items }: { title: string; items: string[] }) {
  return (
    <div className="tag-block">
      <strong>{title}</strong>
      <div className="tags">
        {(items.length > 0 ? items : ["待补充"]).map((item) => (
          <span key={item}>{item}</span>
        ))}
      </div>
    </div>
  );
}

